  FT["PH-H5348"] = {"id":"PH-H5348","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1990/ra_6858_1990.html","fetchedAt":"2026-10-06","articleCount":6,"structureMode":"ARTICLE","title":{"zh":"设立San Fernando市","en":"An Act Establishing a Ten-Bed Municipal Hospital in the Municipality of San Fernando, Province of Bukidnon, to Be Known as the San Fernando Municipal Hospital, and Appropriating Funds Therefor","orig":"An Act Establishing a Ten-Bed Municipal Hospital in the Municipality of San Fernando, Province of Bukidnon, to Be Known as the San Fernando Municipal Hospital, and Appropriating Funds Therefor","vi":"Đạo luật thành lập Bệnh viện Đô thị San Fernando tại Đô thị San Fernando, Tỉnh Bukidnon, và phân bổ kinh phí cho mục đích này","th":"พระราชบัญญัติจัดตั้งโรงพยาบาลเทศบาล San Fernando ในเทศบาล San Fernando จังหวัด Bukidnon และจัดสรรเงินทุนสำหรับการนี้","id":"Undang-Undang membentuk Rumah Sakit Kotamadya San Fernando di Kotamadya San Fernando, Provinsi Bukidnon, dan mengalokasikan dana untuk itu","ms":"Akta menubuhkan Hospital Perbandaran San Fernando di Perbandaran San Fernando, Wilayah Bukidnon, dan memperuntukkan dana untuk itu"},"level":"law","status":"active","topics":["health"],"docNumber":"Republic Act No. 6858","issuingBody":"Congress of the Philippines","promulgatedDate":"1990-03-01","completenessNote":"全文，共 6 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1990/ra_6858_1990.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5348-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There shall be established, under the supervision of the Department of Health, a ten-bed municipal hospital in the Municipality of San Fernando, Province of Bukidnon, to be known as the San Fernando Municipal Hospital."}},{"id":"PH-H5348-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Secretary of Health shall appoint such personnel as may be necessary to carry out the purpose of this Act: Provided, That in no case shall there be less than two (2) attending doctors and no less than four (4) nurses appointed. One of the attending doctors shall be appointed Chief Doctor who shall also act as the administrator of the hospital."}},{"id":"PH-H5348-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The Secretary of Health shall promulgate such rules and regulations as may be necessary to carry out the purpose of this Act: Provided, however , That the Chief Doctor shall have the power to provide for such other rules and regulations not inconsistent with the rules and regulations promulgated by the Secretary of Health as may be necessary to carry out the purpose of this Act."}},{"id":"PH-H5348-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The amount necessary to carry out the provisions of this Act shall be charged against the appropriations authorized for the purpose under the Fiscal Year 1989 General Appropriations Act.\nThereafter, such sums as may be necessary for the operation and maintenance of the herein hospital shall be included in the annual General Appropriations Act."}},{"id":"PH-H5348-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Before the construction of the hospital, the Secretary of health shall issue a written assurance that personnel of the hospital will be appointed and that funds for its maintenance and operation have been appropriated."}},{"id":"PH-H5348-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p76"};
  FT["PH-H5349"] = {"id":"PH-H5349","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1990/ra_6859_1990.html","fetchedAt":"2026-10-06","articleCount":5,"structureMode":"ARTICLE","title":{"zh":"设立Naujan市","en":"An Act Establishing a Ten-Bed Municipal Hospital in the Municipality of Naujan, Province of Oriental Mindoro, to Be Known as the Naujan Municipal Hospital, and Appropriating Funds Therefor","orig":"An Act Establishing a Ten-Bed Municipal Hospital in the Municipality of Naujan, Province of Oriental Mindoro, to Be Known as the Naujan Municipal Hospital, and Appropriating Funds Therefor","vi":"Đạo luật thành lập Bệnh viện Đô thị Naujan tại Đô thị Naujan, Tỉnh Oriental Mindoro, và phân bổ kinh phí cho mục đích này","th":"พระราชบัญญัติจัดตั้งโรงพยาบาลเทศบาล Naujan ในเทศบาล Naujan จังหวัด Oriental Mindoro และจัดสรรเงินทุนสำหรับการนี้","id":"Undang-Undang membentuk Rumah Sakit Kotamadya Naujan di Kotamadya Naujan, Provinsi Oriental Mindoro, dan mengalokasikan dana untuk itu","ms":"Akta menubuhkan Hospital Perbandaran Naujan di Perbandaran Naujan, Wilayah Oriental Mindoro, dan memperuntukkan dana untuk itu"},"level":"law","status":"active","topics":["health"],"docNumber":"Republic Act No. 6859","issuingBody":"Congress of the Philippines","promulgatedDate":"1990-03-01","completenessNote":"全文，共 5 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1990/ra_6859_1990.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5349-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There shall be established, Linder the supervision of the Department of Health, a ten-bed municipal hospital in the Municipality of Naujan, Province of Oriental Mindoro, to be known as the Naujan Municipal Hospital."}},{"id":"PH-H5349-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The hospital shall be constructed in a site to be determined by the Sangguniang Bayan of the Municipality of Naujan, in consultation with the Office of the Secretary of Health."}},{"id":"PH-H5349-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The amount necessary to carry out the provisions of this Act shall be charged against the appropriations authorized for the purpose under the Fiscal Year 1989 General Appropriations Act. Thereafter, such sums as may be necessary for the operation and maintenance of the herein hospital shall be included in the annual General Appropriations Act."}},{"id":"PH-H5349-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Before the construction of the hospital, the Secretary of Health shall issue a written assurance that personnel of the hospital will be appointed and that funds for its maintenance and operation have been appropriated."}},{"id":"PH-H5349-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p76"};
  FT["PH-H5350"] = {"id":"PH-H5350","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1990/ra_6860_1990.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"设立Pinabacdao市","en":"An Act Establishing a Ten-Bed Municipal Hospital in Barangay Parasanon, Municipality of Pinabacdao, Province of Samar, to Be Known as the Pinabacdao Municipal Hospital, and Appropriating Funds Therefor","orig":"An Act Establishing a Ten-Bed Municipal Hospital in Barangay Parasanon, Municipality of Pinabacdao, Province of Samar, to Be Known as the Pinabacdao Municipal Hospital, and Appropriating Funds Therefor","vi":"Đạo luật thành lập Bệnh viện Đô thị Pinabacdao tại Barangay Parasanon, Đô thị Pinabacdao, Tỉnh Samar, và phân bổ kinh phí cho mục đích này","th":"พระราชบัญญัติจัดตั้งโรงพยาบาลเทศบาล Pinabacdao ในบารังไกย์ Parasanon เทศบาล Pinabacdao จังหวัด Samar และจัดสรรเงินทุนสำหรับการนี้","id":"Undang-Undang membentuk Rumah Sakit Kotamadya Pinabacdao di Barangay Parasanon, Kotamadya Pinabacdao, Provinsi Samar, dan mengalokasikan dana untuk itu","ms":"Akta menubuhkan Hospital Perbandaran Pinabacdao di Barangay Parasanon, Perbandaran Pinabacdao, Wilayah Samar, dan memperuntukkan dana untuk itu"},"level":"law","status":"active","topics":["administrative","health"],"docNumber":"Republic Act No. 6860","issuingBody":"Congress of the Philippines","promulgatedDate":"1990-03-01","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1990/ra_6860_1990.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5350-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There shall be established, under the supervision of the Department of Health, a ten-bed municipal hospital in Barangay Parasanon, Municipality of Pinabacdao, Province of Samar, to be known as the Pinabacdao Municipal Hospital."}},{"id":"PH-H5350-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The amount necessary to carry out the provisions of this Act shall be charged against the appropriations authorized for the purpose under the Fiscal Year 1989 General Appropriations Act. Thereafter, such sums as may be necessary for the operation and maintenance of the herein hospital shall be included in the annual General Appropriations Act."}},{"id":"PH-H5350-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Before the construction of the hospital, the Secretary of Health shall issue a written assurance that personnel of the hospital will be appointed and that funds for its maintenance and operation have been appropriated."}},{"id":"PH-H5350-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p76"};
  FT["PH-H5351"] = {"id":"PH-H5351","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1990/ra_6861_1990.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"推迟科迪勒拉自治区州长、副州长与议会成员首次正式选举，为此修订第6766号共和国法（经修正）第一条第21款","en":"An Act Postponing the Holding of the First Regular Election for Governor, Deputy Governor and Members of the Regional Assembly of the Autonomous Region of the Cordilleras, Amending for the Purpose Section 1, Article XXI of Republic Act Numbered Sixty-Seven Hundred and Sixty-Six, as Amended","orig":"An Act Postponing the Holding of the First Regular Election for Governor, Deputy Governor and Members of the Regional Assembly of the Autonomous Region of the Cordilleras, Amending for the Purpose Section 1, Article XXI of Republic Act Numbered Sixty-Seven Hundred and Sixty-Six, as Amended"},"level":"law","status":"active","topics":["administrative"],"docNumber":"Republic Act No. 6861","issuingBody":"Congress of the Philippines","promulgatedDate":"1990-03-08","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1990/ra_6861_1990.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。 源文存在同号重出的条款（第 1 条）：该处官方页面确有两段均标同一 Section 号，本库照录其 `no` 值（不改动官方编号），条文 `id` 以 `_2`「_3」后缀保证唯一。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5351-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Section 1, Article XXI of Republic Act Numbered Sixty-seven hundred and sixty-six, as amended, is hereby further amended to read as follows:\n\""}},{"id":"PH-H5351-A1-d2","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The first regular election for the Cordillera Governor, the Cordillera Deputy Governor and the Members of the Cordillera Assembly shall be held on the first Monday of March 1991. Their terms of office shall begin at noon of the last day of the month next following the proclamation of their election and shall end at noon of the thirty-first day of May 1993. The expenses for the conduct of the election shall be charged against the Contingent Fund; any deficiency shall be taken from the savings of the National Government. The Commission on Elections shall promulgate such rules and regulations as may be necessary for the conduct of said election.\""},"dupIndex":2},{"id":"PH-H5351-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its complete publication in at least two (2) national newspapers and at least one (1) local newspaper of general circulation in Cordillera provinces and Baguio City."}}],"pack":"ph-p76","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Postponing the Holding of the First Regular Election for Governor, Deputy Governor and Members of the Regional Assembly of the Autonomous Region of the Cordilleras, Amending for the Purpose Section 1, Article XXI of Republic Act Numbered Sixty-Seven Hundred and Sixty-Six, as Amended","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H5352"] = {"id":"PH-H5352","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1990/ra_6862_1990.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"设立Cadiz市","en":"An Act Establishing a District Hospital in the City of Cadiz, Province of Negros Occidental, to Be Known as the Cadiz District Hospital, and Appropriating Funds Therefor","orig":"An Act Establishing a District Hospital in the City of Cadiz, Province of Negros Occidental, to Be Known as the Cadiz District Hospital, and Appropriating Funds Therefor","vi":"Đạo luật thành lập Bệnh viện Huyện Cadiz tại Thành phố Cadiz, Tỉnh Negros Occidental, và phân bổ kinh phí cho mục đích này","th":"พระราชบัญญัติจัดตั้งโรงพยาบาลอำเภอ Cadiz ในเมือง Cadiz จังหวัด Negros Occidental และจัดสรรเงินทุนสำหรับการนี้","id":"Undang-Undang membentuk Rumah Sakit Distrik Cadiz di Kota Cadiz, Provinsi Negros Occidental, dan mengalokasikan dana untuk itu","ms":"Akta menubuhkan Hospital Daerah Cadiz di Bandar Cadiz, Wilayah Negros Occidental, dan memperuntukkan dana untuk itu"},"level":"law","status":"active","topics":["health"],"docNumber":"Republic Act No. 6862","issuingBody":"Congress of the Philippines","promulgatedDate":"1990-03-08","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1990/ra_6862_1990.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5352-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There shall be established, under the direct supervision of the Department of Health, a twenty-five-bed district hospital in the City of Cadiz, Province of Negros Occidental, to be known as the Cadiz District Hospital."}},{"id":"PH-H5352-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The amount necessary to carry out the provisions of this Act shall be charged against the appropriations authorized for the purpose under the Fiscal Year 1989 General Appropriations Act. Thereafter, such sums as may be necessary for the operation and maintenance of the herein hospital shall be included in the annual General Appropriations Act."}},{"id":"PH-H5352-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Before the construction of the hospital, the Secretary of Health shall issue a written assurance that personnel of the hospital will be appointed and that funds for its maintenance and operation have been appropriated."}},{"id":"PH-H5352-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p76"};
  FT["PH-H5353"] = {"id":"PH-H5353","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1990/ra_6863_1990.html","fetchedAt":"2026-10-06","articleCount":5,"structureMode":"ARTICLE","title":{"zh":"设立Kibawe市","en":"An Act Establishing a Ten-Bed Municipal Hospital in the Municipality of Kibawe, Province of Bukidnon, to Be Known as the Kibawe Municipal Hospital, and Appropriating Funds Therefor","orig":"An Act Establishing a Ten-Bed Municipal Hospital in the Municipality of Kibawe, Province of Bukidnon, to Be Known as the Kibawe Municipal Hospital, and Appropriating Funds Therefor","vi":"Đạo luật thành lập Bệnh viện Đô thị Kibawe tại Đô thị Kibawe, Tỉnh Bukidnon, và phân bổ kinh phí cho mục đích này","th":"พระราชบัญญัติจัดตั้งโรงพยาบาลเทศบาล Kibawe ในเทศบาล Kibawe จังหวัด Bukidnon และจัดสรรเงินทุนสำหรับการนี้","id":"Undang-Undang membentuk Rumah Sakit Kotamadya Kibawe di Kotamadya Kibawe, Provinsi Bukidnon, dan mengalokasikan dana untuk itu","ms":"Akta menubuhkan Hospital Perbandaran Kibawe di Perbandaran Kibawe, Wilayah Bukidnon, dan memperuntukkan dana untuk itu"},"level":"law","status":"active","topics":["health"],"docNumber":"Republic Act No. 6863","issuingBody":"Congress of the Philippines","promulgatedDate":"1990-03-08","completenessNote":"全文，共 5 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1990/ra_6863_1990.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5353-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There shall be established, under the supervision of the Department of Health, a ten-bed municipal hospital in the Municipality of Kibawe, Province of Bukidnon, to be known as the Kibawe Municipal Hospital."}},{"id":"PH-H5353-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The amount necessary to carry out the provisions of this Act shall be charged against the appropriations authorized for the purpose under the Fiscal Year 1989 General Appropriations Act. Thereafter, such sums as may be necessary for the operation and maintenance of the herein hospital shall be included in the annual General Appropriations Act."}},{"id":"PH-H5353-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"All existing laws, decrees and orders that are inconsistent and contrary with this Act, or any part thereof, shall be deemed repealed, modified, amended and of no effect."}},{"id":"PH-H5353-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Before the construction of the hospital, the Secretary of health shall issue a written assurance that personnel of the hospital will be appointed and that funds for its maintenance and operation have been appropriated."}},{"id":"PH-H5353-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p76"};
  FT["PH-H5354"] = {"id":"PH-H5354","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1990/ra_6864_1990.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"设立Malabon市","en":"An Act Establishing a Ten-Bed Municipal Hospital in the Municipality of Malabon, Metro Manila, to Be Known as the Saint Lorenzo Ruiz Municipal Hospital, and Appropriating Funds Therefor","orig":"An Act Establishing a Ten-Bed Municipal Hospital in the Municipality of Malabon, Metro Manila, to Be Known as the Saint Lorenzo Ruiz Municipal Hospital, and Appropriating Funds Therefor","vi":"Đạo luật thành lập Bệnh viện Đô thị Saint Lorenzo Ruiz tại Đô thị Malabon, Vùng Metro Manila, và phân bổ kinh phí cho mục đích này","th":"พระราชบัญญัติจัดตั้งโรงพยาบาลเทศบาล Saint Lorenzo Ruiz ในเทศบาล Malabon เขตมหานครมะนิลา และจัดสรรเงินทุนสำหรับการนี้","id":"Undang-Undang membentuk Rumah Sakit Kotamadya Saint Lorenzo Ruiz di Kotamadya Malabon, Wilayah Metropolitan Manila, dan mengalokasikan dana untuk itu","ms":"Akta menubuhkan Hospital Perbandaran Saint Lorenzo Ruiz di Perbandaran Malabon, Wilayah Metropolitan Manila, dan memperuntukkan dana untuk itu"},"level":"law","status":"active","topics":["health"],"docNumber":"Republic Act No. 6864","issuingBody":"Congress of the Philippines","promulgatedDate":"1990-03-08","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1990/ra_6864_1990.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5354-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There shall be established, under the supervision of the Department of Health, a ten-bed municipal hospital in the Municipality of Malabon, Metro Manila, to be known as the Saint Lorenzo Ruiz Municipal Hospital. The said hospital shall likewise service the adjoining Municipality of Navotas."}},{"id":"PH-H5354-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The amount necessary to carry out the provisions of this Act shall be charged against the appropriations authorized for the purpose under the Fiscal Year 1989 General Appropriations Act. Thereafter, such sums as may be necessary for the operation and maintenance of the herein hospital shall be included in the annual General Appropriations Act."}},{"id":"PH-H5354-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Before the construction of the hospital, the Secretary of Health shall issue a written assurance that personnel of the hospital will be appointed and that funds for its maintenance and operation have been appropriated."}},{"id":"PH-H5354-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p76"};
  FT["PH-H5355"] = {"id":"PH-H5355","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1990/ra_6865_1990.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"设立Kasibu市","en":"An Act Establishing a Ten-Bed Municipal Hospital in the Municipality of Kasibu, Province of Nueva Vizcaya, to Be Known as the Kasibu Municipal Hospital, and Appropriating Funds Therefor","orig":"An Act Establishing a Ten-Bed Municipal Hospital in the Municipality of Kasibu, Province of Nueva Vizcaya, to Be Known as the Kasibu Municipal Hospital, and Appropriating Funds Therefor","vi":"Đạo luật thành lập Bệnh viện Đô thị Kasibu tại Đô thị Kasibu, Tỉnh Nueva Vizcaya, và phân bổ kinh phí cho mục đích này","th":"พระราชบัญญัติจัดตั้งโรงพยาบาลเทศบาล Kasibu ในเทศบาล Kasibu จังหวัด Nueva Vizcaya และจัดสรรเงินทุนสำหรับการนี้","id":"Undang-Undang membentuk Rumah Sakit Kotamadya Kasibu di Kotamadya Kasibu, Provinsi Nueva Vizcaya, dan mengalokasikan dana untuk itu","ms":"Akta menubuhkan Hospital Perbandaran Kasibu di Perbandaran Kasibu, Wilayah Nueva Vizcaya, dan memperuntukkan dana untuk itu"},"level":"law","status":"active","topics":["health"],"docNumber":"Republic Act No. 6865","issuingBody":"Congress of the Philippines","promulgatedDate":"1990-03-08","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1990/ra_6865_1990.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5355-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There shall be established, under the supervision of the Department of Health, a ten-bed municipal hospital in the Municipality of Kasibu, Province of Nueva Vizcaya, to be known as the Kasibu Municipal Hospital."}},{"id":"PH-H5355-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The amount necessary to carry out the provisions of this Act shall be charged against the appropriations authorized for the purpose under the Fiscal Year 1939 General Appropriations Act. Thereafter, such sums as may be necessary for the operation and maintenance of the herein hospital shall be included in the annual General Appropriations Act."}},{"id":"PH-H5355-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Before the construction of the hospital, the-Secretary of Health shall issue a written assurance that-; personnel of the hospital will be appointed and that funds for its maintenance and operation have been appropriated."}},{"id":"PH-H5355-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval.\nApproved, March 8, 1990."}}],"pack":"ph-p76"};
  FT["PH-H5356"] = {"id":"PH-H5356","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1990/ra_6866_1990.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"设立Dinas市","en":"An Act Establishing a Municipal Hospital in the Municipality of Dinas, Province of Zamboanga Del Sur, to Be Known as the Dinas Municipal Hospital, and Appropriating Funds Therefor","orig":"An Act Establishing a Municipal Hospital in the Municipality of Dinas, Province of Zamboanga Del Sur, to Be Known as the Dinas Municipal Hospital, and Appropriating Funds Therefor","vi":"Đạo luật thành lập Bệnh viện Đô thị Dinas tại Đô thị Dinas, Tỉnh Zamboanga Del Sur, và phân bổ kinh phí cho mục đích này","th":"พระราชบัญญัติจัดตั้งโรงพยาบาลเทศบาล Dinas ในเทศบาล Dinas จังหวัด Zamboanga Del Sur และจัดสรรเงินทุนสำหรับการนี้","id":"Undang-Undang membentuk Rumah Sakit Kotamadya Dinas di Kotamadya Dinas, Provinsi Zamboanga Del Sur, dan mengalokasikan dana untuk itu","ms":"Akta menubuhkan Hospital Perbandaran Dinas di Perbandaran Dinas, Wilayah Zamboanga Del Sur, dan memperuntukkan dana untuk itu"},"level":"law","status":"active","topics":["health"],"docNumber":"Republic Act No. 6866","issuingBody":"Congress of the Philippines","promulgatedDate":"1990-03-08","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1990/ra_6866_1990.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5356-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There shall be established, under the supervision of the Department of Health, a ten-bed municipal hospital in the Municipality of Dinas, Province of Zamboanga del Sur, to be known as the Dinas Municipal Hospital. The said hospital shall also service the adjoining municipalities of Dimataling, Pitogo, Tabina, San Miguel and San Pablo."}},{"id":"PH-H5356-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The amount necessary to carry out the provisions of this Act shall be charged against the appropriations authorized for the purpose under the Fiscal Year 1989 General Appropriations Act. Thereafter, such sums as may be necessary for the operation and maintenance of the herein hospital shall be included in the annual General Appropriations Act."}},{"id":"PH-H5356-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Before the construction of the hospital, the Secretary of Health shall issue a written assurance that personnel of the hospital will be appointed and that funds for its maintenance and operation have been appropriated."}},{"id":"PH-H5356-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p76"};
