  FT["PH-H5372"] = {"id":"PH-H5372","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1990/ra_6882_1990.html","fetchedAt":"2026-10-06","articleCount":6,"structureMode":"ARTICLE","title":{"zh":"设立San Juan市","en":"An Act Establishing a Ten-bed Municipal Hospital in the Municipality of San Juan, Metro Manila, to Be Known as the San Juan Municipal Hospital, and Appropriating Funds Therefor","orig":"An Act Establishing a Ten-bed Municipal Hospital in the Municipality of San Juan, Metro Manila, to Be Known as the San Juan Municipal Hospital, and Appropriating Funds Therefor","vi":"Đạo luật thành lập Bệnh viện Đô thị San Juan tại Đô thị San Juan, Vùng Metro Manila, và phân bổ kinh phí cho mục đích này","th":"พระราชบัญญัติจัดตั้งโรงพยาบาลเทศบาล San Juan ในเทศบาล San Juan เขตมหานครมะนิลา และจัดสรรเงินทุนสำหรับการนี้","id":"Undang-Undang membentuk Rumah Sakit Kotamadya San Juan di Kotamadya San Juan, Wilayah Metropolitan Manila, dan mengalokasikan dana untuk itu","ms":"Akta menubuhkan Hospital Perbandaran San Juan di Perbandaran San Juan, Wilayah Metropolitan Manila, dan memperuntukkan dana untuk itu"},"level":"law","status":"active","topics":["health"],"docNumber":"Republic Act No. 6882","issuingBody":"Congress of the Philippines","promulgatedDate":"1990-03-08","completenessNote":"全文，共 6 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1990/ra_6882_1990.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5372-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Title of Act. — This Act shall be known and cited as \"An Act Establishing a Municipal Hospital in the Municipality of San Juan, Metro Manila.\""}},{"id":"PH-H5372-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Declaration of Policy. — It is the policy of the State to secure the well-being of the people by providing them adequate health services."}},{"id":"PH-H5372-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Creation of the San Juan Municipal Hospital. — There shall be established, under the direct supervision of the Director of Medical Services of the Department of Health, a ten-bed municipal hospital in the Municipality of San Juan, Metro Manila, to be known as the San Juan Municipal Hospital."}},{"id":"PH-H5372-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Appropriations. — The amount necessary to carry out the provisions of this Act shall be charged against the appropriations authorized for the purpose under the Fiscal Year 1989 General Appropriations Act. Thereafter, such sums as may be necessary for the operation and maintenance of the herein hospital shall be included in the annual General Appropriations Act."}},{"id":"PH-H5372-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Before the Construction of the hospital, the Secretary of Health shall issue a written assurance that personnel of the hospital will be appointed and that funds for its maintenance and operation have been appropriated."}},{"id":"PH-H5372-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Effectivity . — This Act shall take effect upon its approval."}}],"pack":"ph-p76"};
  FT["PH-H5373"] = {"id":"PH-H5373","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1990/ra_6883_1990.html","fetchedAt":"2026-10-06","articleCount":5,"structureMode":"ARTICLE","title":{"zh":"设立Hunduan市","en":"An Act Establishing a Ten-Bed Municipal Hospital in the Municipality of Hunduan, Province of Ifugao, to Be Known as the Hungduan Municipal Hospital, and Appropriating Funds Therefor","orig":"An Act Establishing a Ten-Bed Municipal Hospital in the Municipality of Hunduan, Province of Ifugao, to Be Known as the Hungduan Municipal Hospital, and Appropriating Funds Therefor","vi":"Đạo luật thành lập Bệnh viện Đô thị Hungduan tại Đô thị Hunduan, Tỉnh Ifugao, và phân bổ kinh phí cho mục đích này","th":"พระราชบัญญัติจัดตั้งโรงพยาบาลเทศบาล Hungduan ในเทศบาล Hunduan จังหวัด Ifugao และจัดสรรเงินทุนสำหรับการนี้","id":"Undang-Undang membentuk Rumah Sakit Kotamadya Hungduan di Kotamadya Hunduan, Provinsi Ifugao, dan mengalokasikan dana untuk itu","ms":"Akta menubuhkan Hospital Perbandaran Hungduan di Perbandaran Hunduan, Wilayah Ifugao, dan memperuntukkan dana untuk itu"},"level":"law","status":"active","topics":["health"],"docNumber":"Republic Act No. 6883","issuingBody":"Congress of the Philippines","promulgatedDate":"1990-03-08","completenessNote":"全文，共 5 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1990/ra_6883_1990.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5373-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There shall be established, under the direct supervision of the Department of Health, a ten-bed municipal hospital in the Municipality of Hungduan, Province of Ifugao, to be known as the Hungduan Municipal Hospital."}},{"id":"PH-H5373-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Department of Health shall promulgate such rules and regulations as may be necessary to carry out the purpose of this Act."}},{"id":"PH-H5373-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The amount necessary to carry out the provision of this Act shall be charged against the appropriations authorized for the purpose under the Fiscal Year 1989 General Appropriations Act. Thereafter, such sums as may be necessary for the operation and maintenance of the herein hospital shall be included in the annual General Appropriations Act."}},{"id":"PH-H5373-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Before the construction of the hospital, the Secretary of Health shall issue a written assurance that personnel of the hospital will be appointed and that funds for its maintenance and operation have been appropriated."}},{"id":"PH-H5373-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"This Act shall take affect upon its approval.\nApproved, March 8, 1993"}}],"pack":"ph-p76"};
  FT["PH-H5374"] = {"id":"PH-H5374","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1990/ra_6884_1990.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"设立Kananga市","en":"An Act Converting the Kananga Rural Health Center in the Municipality of Kananga, Province of Leyte, Into a Ten-bed Municipal Hospital to Be Known as the Kananga Municipal Hospital, and Appropriating Funds Therefor","orig":"An Act Converting the Kananga Rural Health Center in the Municipality of Kananga, Province of Leyte, Into a Ten-bed Municipal Hospital to Be Known as the Kananga Municipal Hospital, and Appropriating Funds Therefor","vi":"Đạo luật chuyển đổi Trung tâm Y tế Nông thôn Kananga thành Bệnh viện Đô thị Kananga tại Đô thị Kananga, Tỉnh Leyte, và phân bổ kinh phí cho mục đích này","th":"พระราชบัญญัติเปลี่ยนสถานะศูนย์สุขภาพชนบท Kananga เป็น โรงพยาบาลเทศบาล Kananga ในเทศบาล Kananga จังหวัด Leyte และจัดสรรเงินทุนสำหรับการนี้","id":"Undang-Undang mengubah status Pusat Kesehatan Pedesaan Kananga menjadi Rumah Sakit Kotamadya Kananga di Kotamadya Kananga, Provinsi Leyte, dan mengalokasikan dana untuk itu","ms":"Akta menukar status Pusat Kesihatan Luar Bandar Kananga kepada Hospital Perbandaran Kananga di Perbandaran Kananga, Wilayah Leyte, dan memperuntukkan dana untuk itu"},"level":"law","status":"active","topics":["health"],"docNumber":"Republic Act No. 6884","issuingBody":"Congress of the Philippines","promulgatedDate":"1990-03-08","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1990/ra_6884_1990.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5374-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Kananga Rural Health Center in the Municipality of Kananga, Province of Leyte, is hereby converted into a ten-bed municipal hospital to be known as the Kananga Municipal Hospital."}},{"id":"PH-H5374-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The amount necessary to carry out the provisions of this Act shall be charged against the appropriations authorized for the purpose under the Fiscal Year 1989 General Appropriations Act. Thereafter, such sums as may be necessary for the operation and maintenance of the herein hospital shall be included in the annual General Appropriations Act."}},{"id":"PH-H5374-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Before the construction of the hospital, the Secretary of Health shall issue a written assurance that personnel of the hospital will be appointed and that funds for its maintenance and operation have been appropriated."}},{"id":"PH-H5374-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p76"};
