  FT["PH-H5380"] = {"id":"PH-H5380","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1990/ra_6890_1990.html","fetchedAt":"2026-10-06","articleCount":5,"structureMode":"ARTICLE","title":{"zh":"设立Hinoba- 市","en":"An Act Creating a Ten-bed Municipal Hospital With the Necessary Equipment and Supplies in the Municipality of Hinoba-an, Province of Negros Occidental, to Be Known as the Hinoba-an Municipal Hospital, and Appropriating Funds Therefor","orig":"An Act Creating a Ten-bed Municipal Hospital With the Necessary Equipment and Supplies in the Municipality of Hinoba-an, Province of Negros Occidental, to Be Known as the Hinoba-an Municipal Hospital, and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["health"],"docNumber":"Republic Act No. 6890","issuingBody":"Congress of the Philippines","promulgatedDate":"1990-03-08","completenessNote":"全文，共 5 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1990/ra_6890_1990.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5380-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There shall be established, under the direct supervision of the Department of Health, a ten-bed muninicipal hospital with the necessary equipment and supplies in the Municipality of Hinoba-an, Negros Occidental, to be known as the Hinoba-an Municipal Hospital, which shall be under free medical service and accommodation to indigent patients."}},{"id":"PH-H5380-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The municipal hospital shall be administered by the corresponding chiefs of hospital to be appointed by the Secretary of Health and shall receive compensation in accordance with the rates prescribed by the Secretary of Health. With the approval of the Secretary of Health, the chiefs of hospital may allow subsistence quarters and laundry service, in kind, to physicians, nurses or employees of the said hospital, whenever such policy is deemed advisable in the interest of public service."}},{"id":"PH-H5380-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The amount necessary to carry out the provisions of this Act shall be charged against the appropriations authorized for the purpose under the Fiscal Year 1989 General Appropriations Act. Thereafter, such sums as may be necessary for the operation and maintenance of the herein hospital shall be included in the annual General Appropriations Act."}},{"id":"PH-H5380-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Before the construction of the hospital, the Secretary of Health shall issue a written assurance that personnel of the hospital will be appointed and that funds for its maintenance and operation have been appropriated."}},{"id":"PH-H5380-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p76"};
  FT["PH-H5381"] = {"id":"PH-H5381","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1990/ra_6891_1990.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"设立Dasol市","en":"An Act Establishing a Ten-bed Municipal Hospital in the Municipality of Dasol, Province of Pangasinan, to Be Known as the Dasol Municipal Hospital, and Appropriating Funds Therefor","orig":"An Act Establishing a Ten-bed Municipal Hospital in the Municipality of Dasol, Province of Pangasinan, to Be Known as the Dasol Municipal Hospital, and Appropriating Funds Therefor","vi":"Đạo luật thành lập Bệnh viện Đô thị Dasol tại Đô thị Dasol, Tỉnh Pangasinan, và phân bổ kinh phí cho mục đích này","th":"พระราชบัญญัติจัดตั้งโรงพยาบาลเทศบาล Dasol ในเทศบาล Dasol จังหวัด Pangasinan และจัดสรรเงินทุนสำหรับการนี้","id":"Undang-Undang membentuk Rumah Sakit Kotamadya Dasol di Kotamadya Dasol, Provinsi Pangasinan, dan mengalokasikan dana untuk itu","ms":"Akta menubuhkan Hospital Perbandaran Dasol di Perbandaran Dasol, Wilayah Pangasinan, dan memperuntukkan dana untuk itu"},"level":"law","status":"active","topics":["health"],"docNumber":"Republic Act No. 6891","issuingBody":"Congress of the Philippines","promulgatedDate":"1990-03-08","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1990/ra_6891_1990.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5381-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There shall be established, under the direct supervision of the Office of the Secretary of the Department of Health, a ten-bed municipal hospital in the Municipality of Dasol, Province of Pangasinan, to be known as the Dasol Municipal Hospital."}},{"id":"PH-H5381-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The amount necessary to carry out the provisions of this Act shall be charged against the appropriations authorized for the purpose under the Fiscal Year 1989 General Appropriations Act. Thereafter, such sums as may be necessary for the operation and maintenance of the herein hospital shall be included in the annual General Appropriations Act."}},{"id":"PH-H5381-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Before the construction of the hospital, the Secretary of Health shall issue a written assurance that personnel of the hospital will be appointed and that funds for its maintenance and operation have been appropriated."}},{"id":"PH-H5381-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p76"};
